@@ -12,6 +12,7 @@
     { "name": "jq", "kind": "tool", "licence": "MIT", "used": "versions.yml, the runner's own: it reads the issues the versions check would open; and tests/core-moved-test.mjs, which runs through it the expression gh is handed" },
     { "name": "Node.js", "kind": "tool", "version": "26.13.0", "licence": "MIT", "files": ["scripts/node.sh"], "used": "every script: the core's one exact Node, .node-version (the version here moves with it, as the licence scan's pin of a download asks), which scripts/node.sh fetches as the node-linux-x64 or node-linux-arm64 package (npm pack, or curl from the registry with no npm) and checks by its sum where a machine's own Node is below the least long-term line, .node-least, on which the core's suites run too" },
     { "name": "The core's licence and notice", "kind": "data", "licence": "Apache-2.0", "files": ["LICENSE", "NOTICE"], "used": "the licence the core is given under, the Apache License 2.0's own text copied whole, and its notice, the work's name and copyright line (README.md, \"Licence\"; #257): they carry the notice they are, and nothing of the core ships" },
+    { "name": "Semgrep's engine", "kind": "tool", "licence": "LGPL-2.1-or-later", "files": [".packages/requirements.txt", "scripts/install.mjs", "scripts/code-scan.mjs"], "used": "scripts/code-scan.mjs, the code scan of a private project (#546): semgrep-core and the libraries beside it, from the semgrep wheel for each system, which requirements.txt names by version and SHA-256 and scripts/install.mjs pypi installs with pip, no dependency and none of its code run, in the scan's own step (#654); run as osemgrep with no Python; a tool that only runs, nothing of which ships, so floor rule 10 allows its LGPL. Its rules are the core's own (scripts/code-scan.yml); none of Semgrep's rules, under the Semgrep Rules License, or Opengrep's, under the Commons Clause, is taken. The licence check reads no requirements file, so this entry holds it. Its wheels' PyPI attestation is published by GitHub, semgrep/semgrep-proprietary, workflow pro-release.yml, at 1.185.0, the baseline an update is held to (floor rule 7)" },
     { "name": "npm", "kind": "tool", "licence": "Artistic-2.0", "used": "bundled with Node: npm view in versions.mjs, npm pack in node.sh, npm ci and npm audit signatures in signatures.yml, npm ci in scripts/install.mjs, and npm audit signatures on the core's own packages in tests.yml" }
   ]
 }

